-- READ-ONLY episode-level zero outTemp run-length screen.
WITH targets AS (SELECT 1406148900 AS left_time, 1406150100 AS right_time, '2014:1406148900:1406150100' AS gap_id, 1200 AS gap_seconds, 'lt_1h' AS gap_band UNION ALL SELECT 1406151900, 1406154300, '2014:1406151900:1406154300', 2400, 'lt_1h' UNION ALL SELECT 1406154900, 1406155500, '2014:1406154900:1406155500', 600, 'lt_1h' UNION ALL SELECT 1406156400, 1406159700, '2014:1406156400:1406159700', 3300, 'lt_1h' UNION ALL SELECT 1406160000, 1406161500, '2014:1406160000:1406161500', 1500, 'lt_1h' UNION ALL SELECT 1406163300, 1406164200, '2014:1406163300:1406164200', 900, 'lt_1h' UNION ALL SELECT 1406165100, 1406166300, '2014:1406165100:1406166300', 1200, 'lt_1h' UNION ALL SELECT 1406166600, 1406168700, '2014:1406166600:1406168700', 2100, 'lt_1h' UNION ALL SELECT 1406170800, 1406171400, '2014:1406170800:1406171400', 600, 'lt_1h' UNION ALL SELECT 1406214300, 1406215500, '2014:1406214300:1406215500', 1200, 'lt_1h' UNION ALL SELECT 1406218500, 1406219100, '2014:1406218500:1406219100', 600, 'lt_1h' UNION ALL SELECT 1406219700, 1406220600, '2014:1406219700:1406220600', 900, 'lt_1h' UNION ALL SELECT 1406222700, 1406225700, '2014:1406222700:1406225700', 3000, 'lt_1h' UNION ALL SELECT 1406226000, 1406227200, '2014:1406226000:1406227200', 1200, 'lt_1h' UNION ALL SELECT 1406228700, 1406231100, '2014:1406228700:1406231100', 2400, 'lt_1h' UNION ALL SELECT 1406231700, 1406237100, '2014:1406231700:1406237100', 5400, '1h_to_lt_1d' UNION ALL SELECT 1406237400, 1406313000, '2014:1406237400:1406313000', 75600, '1h_to_lt_1d' UNION ALL SELECT 1406363400, 1406396700, '2014:1406363400:1406396700', 33300, '1h_to_lt_1d' UNION ALL SELECT 1406396700, 1406400000, '2014:1406396700:1406400000', 3300, 'lt_1h' UNION ALL SELECT 1406400000, 1406400600, '2014:1406400000:1406400600', 600, 'lt_1h' UNION ALL SELECT 1406407500, 1406408100, '2014:1406407500:1406408100', 600, 'lt_1h' UNION ALL SELECT 1406408700, 1406409600, '2014:1406408700:1406409600', 900, 'lt_1h' UNION ALL SELECT 1406409600, 1406411100, '2014: