7139800, 1407140400, '2014:1407139800:1407140400', 600, 'lt_1h' UNION ALL SELECT 1407141000, 1407141600, '2014:1407141000:1407141600', 600, 'lt_1h' UNION ALL SELECT 1407142200, 1407142800, '2014:1407142200:1407142800', 600, 'lt_1h' UNION ALL SELECT 1407143400, 1407144000, '2014:1407143400:1407144000', 600, 'lt_1h' UNION ALL SELECT 1407144600, 1407145200, '2014:1407144600:1407145200', 600, 'lt_1h' UNION ALL SELECT 1407145800, 1407146400, '2014:1407145800:1407146400', 600, 'lt_1h' UNION ALL SELECT 1407147000, 1407147600, '2014:1407147000:1407147600', 600, 'lt_1h' UNION ALL SELECT 1407148200, 1407148800, '2014:1407148200:1407148800', 600, 'lt_1h' UNION ALL SELECT 1407149400, 1407150000, '2014:1407149400:1407150000', 600, 'lt_1h' UNION ALL SELECT 1407150600, 1407151200, '2014:1407150600:1407151200', 600, 'lt_1h' UNION ALL SELECT 1407151800, 1407152400, '2014:1407151800:1407152400', 600, 'lt_1h' UNION ALL SELECT 1407153000, 1407153600, '2014:1407153000:1407153600', 600, 'lt_1h' UNION ALL SELECT 1407154200, 1407154800, '2014:1407154200:1407154800', 600, 'lt_1h' UNION ALL SELECT 1407155400, 1407156000, '2014:1407155400:1407156000', 600, 'lt_1h' UNION ALL SELECT 1407156600, 1407157200, '2014:1407156600:1407157200', 600, 'lt_1h' UNION ALL SELECT 1407157800, 1407158400, '2014:1407157800:1407158400', 600, 'lt_1h' UNION ALL SELECT 1407159000, 1407159600, '2014:1407159000:1407159600', 600, 'lt_1h' UNION ALL SELECT 1407160200, 1407160800, '2014:1407160200:1407160800', 600, 'lt_1h' UNION ALL SELECT 1407588300, 1407597300, '2014:1407588300:1407597300', 9000, '1h_to_lt_1d' UNION ALL SELECT 1407690000, 1407691200, '2014:1407690000:1407691200', 1200, 'lt_1h' UNION ALL SELECT 1408783500, 1408784100, '2014:1408783500:1408784100', 600, 'lt_1h' UNION ALL SELECT 1408784400, 1408785300, '2014:1408784400:1408785300', 900, 'lt_1h' UNION ALL SELECT 1410880500, 1410883800, '2014:1410880500:1410883800', 3300, 'lt_1h' UNION ALL SELECT 1410891300, 1410891900, '2014:1410891300:1410891900', 600, 'lt_1h' UNION ALL SELECT 1410892200, 1410893700, '2014:1410892200:1410893700', 1500, 'lt_1h' UNION ALL SELECT 1410894600, 1410898500, '2014:1410894600:1410898500', 3900, '1h_to_lt_1d' UNION ALL SELECT 1410899100, 1410899700, '2014:1410899100:1410899700', 600, 'lt_1h' UNION ALL SELECT 1410900000, 1410900600, '2014:1410900000:1410900600', 600, 'lt_1h' UNION ALL SELECT 1410900900, 1410937800, '2014:1410900900:1410937800', 36900, '1h_to_lt_1d' UNION ALL SELECT 1419831300, 1419831900, '2014:1419831300:1419831900', 600, 'lt_1h' UNION ALL SELECT 1419836100, 1419836700, '2014:1419836100:1419836700', 600, 'lt_1h'), wh_rows AS (
 SELECT t.gap_id,t.gap_band,t.left_time,t.right_time,a.dateTime ts,a.outTemp,
        CASE WHEN a.dateTime>=1514764800 AND a.dateTime<1522540800 THEN 'PROTECTED_Q1_2018_DIAGNOSTIC' ELSE 'NORMAL' END protection_scope
 FROM targets t JOIN weewx_WH1080.archive a
   ON a.dateTime>t.left_time AND a.dateTime<t.right_time AND MOD(a.dateTime-t.left_time,300)=0
 LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime
 WHERE r.dateTime IS NULL
), lagged AS (
 SELECT *,LAG(ts) OVER(PARTITION BY gap_id ORDER BY ts) prev_ts,
          LAG(outTemp) OVER(PARTITION BY gap_id ORDER BY ts) prev_temp,
          LEAD(ts) OVER(PARTITION BY gap_id ORDER BY ts) next_ts,
          LEAD(outTemp) OVER(PARTITION BY gap_id ORDER BY ts) next_temp
 FROM wh_rows
), marked AS (
 SELECT *,CASE WHEN outTemp=0 AND COALESCE(prev_ts=ts-300 AND prev_temp=0,0)=0 THEN 1 ELSE 0 END zero_run_start
 FROM lagged
), segmented AS (
 SELECT *,SUM(zero_run_start) OVER(PARTITION BY gap_id ORDER BY ts ROWS UNBOUNDED PRECEDING) zero_run_id
 FROM marked
), runs AS (
 SELECT CAST(SUBSTRING_INDEX(gap_id,':',1) AS UNSIGNED) utc_year,gap_band,protection_scope,
        gap_id,zero_run_id,COUNT(*) sample_count,MIN(ts) first_ts,MAX(ts) last_ts,
        MAX(CASE WHEN zero_run_start=1 AND prev_ts=ts-300 THEN prev_temp END) left_neighbor_temp,
        MAX(CASE WHEN next_ts=ts+300 AND next_temp<>0 THEN next_temp END) right_neighbor_temp
 FROM segmented WHERE outTemp=0
 GROUP BY utc_year,gap_band,protection_scope,gap_id,zero_run_id
)
SELECT utc_year,gap_band,protection_scope,COUNT(*) zero_run_count,
       SUM(sample_count) zero_samples,SUM(sample_count=1) singleton_runs,
       SUM(sample_count BETWEEN 2 AND 5) runs_2_to_5,
       SUM(sample_count BETWEEN 6 AND 11) runs_6_to_11,
       SUM(sample_count>=12) runs_12_plus,MAX(sample_count) max_run_samples,
       COUNT(DISTINCT gap_id) gaps_with_zero_run,
       SUM(left_neighbor_temp IS NOT NULL AND right_neighbor_temp IS NOT NULL) runs_bracketed_by_nonzero,
       SUM(left_neighbor_temp IS NOT NULL AND right_neighbor_temp IS NOT NULL AND left_neighbor_temp<>right_neighbor_temp) bracketed_with_change
FROM runs GROUP BY utc_year,gap_band,protection_scope ORDER BY utc_year,gap_band,protection_scope
